using MediatR;using Namaa.Application.Abstractions.Persistence;using Namaa.Application.JournalEntries.Dtos;using Namaa.Domain.Common.Errors;using Namaa.Domain.Common.Results;namespace Namaa.Application.JournalEntries.Commands.PostJournalEntry;public sealed class PostJournalEntryCommandHandler(IJournalEntryRepository repository,IUserRepository users,IApplicationDbContext db):IRequestHandler<PostJournalEntryCommand,Result<JournalEntryDto>>{public async Task<Result<JournalEntryDto>>Handle(PostJournalEntryCommand request,CancellationToken cancellationToken){var e=await repository.FindForUpdateAsync(request.Id,cancellationToken);if(e is null)return Result.Failure<JournalEntryDto>(JournalEntryErrors.NotFound);if(e.Status!="Draft")return Result.Failure<JournalEntryDto>(JournalEntryErrors.NotDraft);if(e.Lines.Count==0||e.Lines.Sum(x=>x.Debit)!=e.Lines.Sum(x=>x.Credit))return Result.Failure<JournalEntryDto>(JournalEntryErrors.Unbalanced);if(!await users.ExistsByIdAsync(request.PostedByUserId,cancellationToken))return Result.Failure<JournalEntryDto>(new Error("JournalEntries.UserNotFound","The posting user was not found.",ErrorType.NotFound));e.Post(request.PostedByUserId,request.PostedAt);await db.SaveChangesAsync(cancellationToken);return Result.Success(JournalEntryDto.FromEntity(e));}}
